#include <Arduino.h>
#include <Servo.h>

static const int SERVO_PIN = 15;
static const int POT_PIN = A0;
Servo myServo;

void setup() {
  myServo.attach(SERVO_PIN);
  Serial1.setTX(0);
  Serial1.setRX(1);
  Serial1.begin(115200);
  Serial1.println("SERVO_POT_HARDWARE_READY");
}

void loop() {
  const int raw = analogRead(POT_PIN);
  // Map 0-1023 (10-bit ADC) to 0-180 degrees
  const int angle = map(raw, 0, 1023, 0, 180);

  myServo.write(angle);

  static uint32_t lastLog = 0;
  if (millis() - lastLog > 100) {
    Serial1.print("POT=");
    Serial1.print(raw);
    Serial1.print(" ANG=");
    Serial1.println(angle);
    lastLog = millis();
  }
  delay(20);
}

